function toast(m){const d=document.createElement('div');d.className='toast';d.textContent=m;$('#toast-root').appendChild(d);setTimeout(()=>d.remove(),4200)}
function modal(html){$('#modal-root').innerHTML=`<div class="modal-bg" onclick="if(event.target===this)closeModal()"><div class="modal" role="dialog" aria-modal="true">${html}</div></div>`}
function closeModal(){$('#modal-root').innerHTML=''}
function go(h){location.hash=h}
function setLang(l){lang=l;localStorage.setItem('midjuman_lang',l);const u=me();if(u){u.lang=l;saveDB()}render()}
function requireAuth(){if(!me()){go('#/login');return false}return true}
function logo(){return`<a class="logo" href="#/"><i>M</i><span>Midju<em>man</em></span></a>`}
function publicNav(active){return`<header class="mnav"><div class="container mnav-in">${logo()}<nav><a href="#/templates">${T().templates}</a><a href="#features">${L('Fonctionnalités','Features')}</a><a href="#ai">Midjuman AI</a><a href="#ats">ATS</a><a href="#/pricing">${T().pricing}</a></nav><div class="nav-r"><button class="lang-btn" onclick="setLang(lang==='fr'?'en':'fr')">${lang==='fr'?'EN':'FR'}</button>${me()?`<a class="btn btn-out btn-sm" href="#/app">${T().dashboard}</a><a class="btn btn-pri btn-sm" href="#/app">${esc(me().firstName)}</a>`:`<a class="btn btn-ghost btn-sm" href="#/login">${T().login}</a><a class="btn btn-pri btn-sm" href="#/register">${T().create}</a>`}<button class="burger" onclick="document.querySelector('.mnav nav').style.display='flex'">☰</button></div></div></header>`}
function footer(){return`<footer class="footer"><div class="container rowflex"><div>${logo()}<p>Build a CV that gets you noticed. · Créez un CV qui vous fait remarquer.</p></div><span class="grow"></span><span>© 2026 Midjuman — ${L('Vos données vous appartiennent.','Your data belongs to you.')}</span></div></footer>`}
/* ---------- HERO SAMPLE ---------- */
function heroResume(){const r=JSON.parse(JSON.stringify(DB.resumes[0]||sampleHeroFallback()));return r}
function sampleHeroFallback(){return sampleResume('x','Demo','Chef de Projet','meridian',['Aïcha','Diallo','Chef de Projet Digital','aicha@example.com',''], [{title:'Chef de Projet',company:'Orange',start:'2021',end:'',current:true,bullets:['Conversion +28% en 6 mois']}],['Agile','Figma'])}
let heroTpl='meridian',heroAccent='';
