function animateCounts(){document.querySelectorAll('[data-count]').forEach(el=>{const target=+el.dataset.count;let v=0;const iv=setInterval(()=>{v+=Math.ceil(target/28);if(v>=target){v=target;clearInterval(iv)}el.textContent=v.toLocaleString('fr-FR')+'+'},35)})}
function demoAI(){$('#ai-after').textContent=improveBullet($('#ai-before').textContent);track('ai_demo')}
function filterBar(active){return`<div class="filterbar">${CATS.map(c=>`<button class="chip ${c===active?'on':''}" onclick="filterTpls('${c}',this)">${c}</button>`).join('')}</div>`}
function filterTpls(cat,btn){document.querySelectorAll('.filterbar .chip').forEach(b=>b.classList.remove('on'));if(btn)btn.classList.add('on');const list=TEMPLATES.filter(t=>cat==='All'||t.cat===cat||(cat==='Modern'&&['Modern','Tech'].includes(t.cat))).filter(t=>DB.published[t.id]!==false);$('#tpl-grid').innerHTML=list.length?list.map(tplCard).join(''):`<div class="empty" style="grid-column:1/-1"><h3>${L('Aucun modèle dans cette catégorie pour le moment.','No template in this category yet.')}</h3></div>`}
function tplCard(t){return`<div class="tpl-card" onclick="useTemplate('${t.id}')"><div class="tpl-thumb">${renderCV(tplSample(t),true)}</div><div class="tpl-meta"><div><b>${t.name}</b><span>${t.cat} · ${t.hFont}</span></div><div style="display:grid;gap:4px;justify-items:end"><span class="ats-pill ${t.ats<88?'mid':''}">ATS ${t.ats}</span>${t.premium?'<span class="pro-pill">PRO</span>':''}</div></div></div>`}
let _tplSampleCache={};
function tplSample(t){if(_tplSampleCache[t.id])return _tplSampleCache[t.id];const base=heroResume();base.templateId=t.id;base.design={...base.design,accent:'',hFont:'',bFont:'',layout:''};return _tplSampleCache[t.id]=base}
function useTemplate(id){const t=tpl(id);if(!me()){sessionStorage.setItem('pending_tpl',id);go('#/register');toast(L('Créez votre compte gratuit pour utiliser ce modèle.','Create your free account to use this template.'));return}createResume(id)}
function faqHTML(){const faqs=[[L('Mes CV sont-ils compatibles ATS ?','Are my CVs ATS-compatible?'),L('Oui — nos modèles étiquetés ATS utilisent une mise en page simple, des sections standard et des polices lisibles par machine. L’analyseur ATS vous donne un score détaillé et des corrections. Nous ne prétendons pas garantir le passage de tous les systèmes.','Yes — ATS-labelled templates use simple layouts, standard sections and machine-readable fonts. The ATS analyzer gives a detailed score and fixes. We do not claim to guarantee every system.')],[L('Mes données sont-elles privées ?','Is my data private?'),L('Vos données vous appartiennent. Elles ne sont jamais vendues. Vous pouvez exporter ou supprimer votre compte à tout moment.','Your data belongs to you, is never sold, and you can export or delete your account anytime.')],[L('Puis-je exporter en PDF et Word ?','Can I export PDF and Word?'),L('Oui : PDF prêt à imprimer (A4/Letter), Word .docx entièrement éditable, PowerPoint .pptx et page web partageable.','Yes: print-ready PDF (A4/Letter), fully editable .docx, .pptx and a shareable web page.')],[L('Comment fonctionne Midjuman AI ?','How does Midjuman AI work?'),L('Midjuman AI réécrit vos phrases en réalisations mesurables, génère des résumés, suggère des compétences et compare votre CV à une offre. Vous gardez toujours le contrôle final.','Midjuman AI rewrites bullets into measurable achievements, generates summaries, suggests skills and matches job descriptions. You always stay in control.')],[L('Puis-je annuler mon abonnement ?','Can I cancel anytime?'),L('Oui, en un clic depuis Facturation. Vous conservez l’accès jusqu’à la fin de la période payée.','Yes, in one click from Billing. You keep access until the end of the paid period.')],[L('Quels moyens de paiement ?','Which payment methods?'),L('Carte bancaire et, selon votre région, Mobile Money. Notre couche de paiement permet d’ajouter de nouveaux moyens sans refonte.','Cards and, depending on region, Mobile Money. Our payment layer allows new methods without redesign.')]];return faqs.map(f=>`<details class="faq"><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('')}
function pricingHTML(yearly){const cur=localStorage.getItem('mj_cur')||'FCFA';const rates={USD:['$',9,19],EUR:['€',8,17],FCFA:['FCFA',4900,9900]};const[sym,pro,career]=rates[cur];const f=n=>cur==='FCFA'?n.toLocaleString('fr-FR'):n;
 const plan=(name,price,per,feats,pop,cta)=>`<div class="price ${pop?'pop':''}">${pop?'<span class="badge" style="position:absolute;top:-13px;right:18px">★ Populaire</span>':''}<h3 style="margin:0;color:var(--dark)">${name}</h3><div class="amt">${price}<span style="font-size:15px;color:var(--mut)">${per}</span></div><ul>${feats.map(x=>`<li>${x}</li>`).join('')}</ul><button class="btn ${pop?'btn-pri':'btn-out'} btn-block" onclick="${cta}">${name==='Free'?L('Commencer gratuitement','Start free'):L('Choisir '+name,'Choose '+name)}</button></div>`;
 return`<div class="center mb"><div class="toggle"><button class="${!yearly?'on':''}" onclick="render()">${L('Mensuel','Monthly')}</button><button class="${yearly?'on':''}" onclick="toast('${L('Astuce : l’annuel = 2 mois offerts dans la facturation.','Tip: yearly = 2 months free at checkout.')}')">${L('Annuel −17%','Yearly −17%')}</button></div> <select class="inp" style="width:auto;display:inline-block" onchange="localStorage.setItem('mj_cur',this.value);render()">${['FCFA','USD','EUR'].map(c=>`<option ${c===cur?'selected':''}>${c}</option>`).join('')}</select></div>
 <div class="cards3">${plan('Free','0 '+sym,' /'+L('toujours','forever'),[L('1 CV','1 CV'),L('Modèles gratuits','Free templates'),L('Éditeur essentiel','Basic editor'),L('Aperçu ATS limité','Limited ATS preview'),L('Export PDF','PDF export')],'',"go('#/register')")}${plan('Pro',f(pro)+' '+sym,' /'+L('mois','month'),[L('CV illimités','Unlimited CVs'),L('Les 24 modèles premium','All 24 premium templates'),'Midjuman AI',L('Analyse ATS complète','Full ATS analysis'),'Word + PowerPoint',L('CV web public','Public web CV'),L('Lettres de motivation','Cover letters')],true,`checkout('Pro',${pro},'${cur}')`)}${plan('Career Pro',f(career)+' '+sym,' /'+L('mois','month'),[L('Tout Pro inclus','Everything in Pro'),L('Optimisation par offre','Job-specific optimization'),L('Suivi candidatures','Job tracker'),L('Historique de versions','Version history'),L('Analytique avancée','Advanced analytics'),L('Support prioritaire','Priority support')],false,`checkout('Career Pro',${career},'${cur}')`)}</div>
 <div class="panel mt center"><b>${L('Pas d’abonnement ?','No subscription?')}</b> <span class="small">${L('Payez uniquement le CV dont vous avez besoin :','Pay only for the CV you need:')}</span> <span class="badge badge-warm">3 000 FCFA / CV</span> <button class="btn btn-dark btn-sm" onclick="checkout('Single CV',3000,'FCFA')">${L('Acheter un CV','Buy one CV')}</button></div>`}
function viewTemplatesPage(){app.innerHTML=publicNav()+`<section class="section"><div class="container"><div class="sec-head"><span class="badge">${L('24 modèles','24 templates')}</span><h2>${L('Prévisualisez avant de vous inscrire.','Preview before you sign up.')}</h2><p>${L('Cliquez sur un modèle pour commencer immédiatement avec vos propres informations.','Click a template to start instantly with your own details.')}</p></div>${filterBar('All')}<div class="tpl-grid" id="tpl-grid">${TEMPLATES.map(tplCard).join('')}</div></div></section>`+footer()}
function viewPricingPage(){app.innerHTML=publicNav()+`<section class="section"><div class="container"><div class="sec-head"><h2>${L('Tarifs Midjuman','Midjuman pricing')}</h2></div>${pricingHTML()}<div style="max-width:820px;margin:40px auto 0">${faqHTML()}</div></div></section>`+footer()}
